-- 0001_init.sql — initial DevMail schema.
-- All timestamps are UTC; UUIDs are generated by PostgreSQL.

CREATE TABLE IF NOT EXISTS users (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    email         text NOT NULL UNIQUE,
    name          text NOT NULL DEFAULT '',
    role          text NOT NULL DEFAULT 'operator'
                  CHECK (role IN ('super_admin','server_admin','domain_admin','operator')),
    password_hash text NOT NULL,
    totp_secret   text,
    is_active     boolean NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sessions (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash text NOT NULL UNIQUE,
    ip         text NOT NULL DEFAULT '',
    user_agent text NOT NULL DEFAULT '',
    expires_at timestamptz NOT NULL,
    revoked    boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);

CREATE TABLE IF NOT EXISTS audit_log (
    id            bigserial PRIMARY KEY,
    user_id       uuid REFERENCES users(id) ON DELETE SET NULL,
    actor_email   text NOT NULL DEFAULT '',
    action        text NOT NULL,
    resource_type text NOT NULL DEFAULT '',
    resource_id   text NOT NULL DEFAULT '',
    detail        jsonb,
    ip            text NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_log(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_user ON audit_log(user_id);

CREATE TABLE IF NOT EXISTS settings (
    key        text PRIMARY KEY,
    value      jsonb NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS servers (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name            text NOT NULL,
    hostname        text NOT NULL UNIQUE,
    ipv4            inet,
    ipv6            inet,
    location        text NOT NULL DEFAULT '',
    environment     text NOT NULL DEFAULT 'production',
    notes           text NOT NULL DEFAULT '',
    status          text NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','healthy','degraded','offline','disabled','maintenance')),
    maintenance     boolean NOT NULL DEFAULT false,
    last_check_at   timestamptz,
    last_check_error text NOT NULL DEFAULT '',
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    deleted_at      timestamptz
);

CREATE TABLE IF NOT EXISTS server_health (
    id         bigserial PRIMARY KEY,
    server_id  uuid NOT NULL REFERENCES servers(id) ON DELETE CASCADE,
    status     text NOT NULL,
    latency_ms bigint NOT NULL DEFAULT 0,
    addr       text NOT NULL DEFAULT '',
    checked_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_server_health ON server_health(server_id, checked_at DESC);

CREATE TABLE IF NOT EXISTS domain_check_results (
    id         bigserial PRIMARY KEY,
    domain_id  uuid NOT NULL,
    kind       text NOT NULL,
    ok         boolean NOT NULL,
    detail     jsonb,
    checked_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_domain_checks_domain ON domain_check_results(domain_id, checked_at DESC);

CREATE TABLE IF NOT EXISTS domains (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name             text NOT NULL UNIQUE,
    server_id        uuid REFERENCES servers(id) ON DELETE SET NULL,
    status           text NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('pending','verified','provisioning','active','degraded','suspended','failed')),
    verification_token text NOT NULL DEFAULT '',
    verified_at      timestamptz,
    catch_all        boolean NOT NULL DEFAULT false,
    quota_bytes      bigint NOT NULL DEFAULT 0,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    deleted_at       timestamptz
);
CREATE INDEX IF NOT EXISTS idx_domains_server ON domains(server_id);

CREATE TABLE IF NOT EXISTS mailboxes (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    domain_id       uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,
    local           text NOT NULL,
    display_name    text NOT NULL DEFAULT '',
    quota_bytes     bigint NOT NULL DEFAULT 0,
    status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')),
    engine_status   text NOT NULL DEFAULT 'unmanaged',
    password_set_at timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    deleted_at      timestamptz,
    UNIQUE (domain_id, local)
);
CREATE INDEX IF NOT EXISTS idx_mailboxes_domain ON mailboxes(domain_id);

CREATE TABLE IF NOT EXISTS aliases (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    domain_id   uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,
    source      text NOT NULL,
    destination text NOT NULL,
    forwarding  boolean NOT NULL DEFAULT false,
    enabled     boolean NOT NULL DEFAULT true,
    created_at  timestamptz NOT NULL DEFAULT now(),
    deleted_at  timestamptz,
    UNIQUE (domain_id, source)
);
CREATE INDEX IF NOT EXISTS idx_aliases_domain ON aliases(domain_id);

CREATE TABLE IF NOT EXISTS jobs (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    kind        text NOT NULL,
    status      text NOT NULL DEFAULT 'queued'
                CHECK (status IN ('queued','running','succeeded','failed','retrying','cancelled')),
    payload     jsonb,
    result      jsonb,
    error       text NOT NULL DEFAULT '',
    attempts    integer NOT NULL DEFAULT 0,
    max_attempts integer NOT NULL DEFAULT 3,
    run_at      timestamptz NOT NULL DEFAULT now(),
    started_at  timestamptz,
    finished_at timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_jobs_status ON jobs(status, run_at);

